    "subTopics": [
      {
        "id": "sub-1",
        "title": "1. The 3-Phase Market Cycle (Impulse, Absorption, Displacement)",
        "content": "\n          <p class=\"mb-3\">A Morning Star is the textbook 3-bar reversal cycle:</p>\n          <ul class=\"list-disc pl-5 mb-4 space-y-1.5 text-xs text-gray-300\">\n            <li><strong>Bar 1 (Impulse):</strong> Strong bearish expansion candle showing retail capitulation.</li>\n            <li><strong>Bar 2 (Absorption Star):</strong> Narrow-range indecision bar (spinning top or doji) gapping or dipping lower, showing seller exhaustion.</li>\n            <li><strong>Bar 3 (Displacement):</strong> Aggressive green candle driving violently upwards, closing deep inside Bar 1's territory.</li>\n          </ul>\n        "
      },
      {
        "id": "sub-2",
        "title": "2. The 50% Midpoint Rule: Validating Real Institutional Footprints",
        "content": "\n          <p class=\"mb-3\">The golden rule for top prop-desk analysts: <strong>Bar 3 MUST close above the 50% midpoint of Bar 1's body</strong>. If Bar 3 closes below the 50% line, it is a weak attempt that sellers are likely to crush.</p>\n        "
      },
      {
        "id": "sub-3",
        "title": "3. Volume Footprint Signature Across the 3 Bars",
        "content": "\n          <p class=\"mb-3\">Watch volume closely: Bar 1 has heavy selling volume, Bar 2 shows volume dry-up (no more sellers left), and Bar 3 brings an explosive institutional volume spike.</p>\n        "
      }
    ],
    "tradeDetails": {
      "setupType": "3-Bar Trend Exhaustion Reversal",
      "instrument": "SENSEX Spot / ATM Call Option",
      "entryTrigger": "At close of Bar 3 once 50% midpoint of Bar 1 is penetrated",
      "stopLoss": "1 tick below the low of the middle star bar (-150 pts)",
      "target1": "Previous swing pivot high (+300 pts / 1:2 RR)",
      "target2": "Higher timeframe supply zone (+480 pts / 1:3.2 RR)",
      "riskReward": "1:3.2",
      "executionChecklist": [
        "Bar 1 is a healthy, full-bodied red candle",
        "Bar 2 shows small body and indecision wicks at the low",
        "Bar 3 closes convincingly above the 50% midpoint of Bar 1",
        "Volume increases on Bar 3 compared to Bar 2"
      ],
      "pitfalls": [
        "Entering on Bar 2 before confirmation (Bar 2 can just be a pause in a heavy downtrend)",
        "Ignoring Bar 3 closing below the 50% midpoint"
      ]
    },
