    "subTopics": [
      {
        "id": "sub-1",
        "title": "1. Geometry of W & M Formations: Failed Auction Mechanics",
        "content": "\n          <p class=\"mb-3\">A Double Bottom (W Pattern) develops when a downtrend hits a strong buyer wall (Leg 1), bounces to an intermediate peak (Neckline), and drops back to test the low (Leg 2).</p>\n          <p class=\"mb-3\">The failure of sellers to push price lower on Leg 2 proves that seller aggression has dried up. The balance of supply and demand flips heavily into buyers' favor.</p>\n        "
      },
      {
        "id": "sub-2",
        "title": "2. The Leg 2 Liquidity Sweep Phenomenon (Turtle Soup Stop Run)",
        "content": "\n          <p class=\"mb-3\">The highest win-rate W formations do not have equal bottoms. In fact, <strong>Leg 2 dips slightly below Leg 1 by 10 to 30 points on Nifty</strong>, sweeps all the protective stops of early buyers, and immediately closes back above the Leg 1 low.</p>\n          <p class=\"mb-3\">This false breakdown traps breakout short-sellers and provides smart money with the liquidity they need to launch an explosive rally.</p>\n        "
      },
      {
        "id": "sub-3",
        "title": "3. Measured Move Projections (100% & 161.8% Extensions)",
        "content": "\n          <p class=\"mb-3\">To calculate your exit target scientifically, measure the vertical distance from the lowest bottom to the neckline ($H$).</p>\n          <div class=\"bg-tradeDark p-3 rounded-lg border border-tradeBorder font-mono text-xs text-accentGold my-2\">\n            Target 1 (100% Measured Move) = Neckline Level + H<br>\n            Target 2 (1.618 Fib Extension) = Neckline Level + (H &times; 1.618)\n          </div>\n        "
      }
    ],
    "tradeDetails": {
      "setupType": "Turtle Soup Leg-2 Sweep & Neckline Expansion",
      "instrument": "NIFTY Spot / ATM Call Option",
      "entryTrigger": "Conservative: Neckline breakout & retest | Aggressive: Leg-2 reclaim of Leg-1 low",
      "stopLoss": "1 tick below the lowest point of Leg 2 (-65 pts)",
      "target1": "100% Measured move distance above neckline (+140 pts / 1:2.1 RR)",
      "target2": "1.618 Fibonacci expansion extension (+220 pts / 1:3.4 RR)",
      "riskReward": "1:3.4",
      "executionChecklist": [
        "Leg 2 shows lower volume during drop than Leg 1",
        "Leg 2 forms rejection wick or immediate bullish engulfing candle",
        "Neckline breakout occurs with expanding volume bar",
        "Wait for retest of broken neckline on 5-min chart"
      ],
      "pitfalls": [
        "Buying too early inside the consolidation without waiting for Leg 2 to confirm",
        "Ignoring severe overhead resistance just above the neckline"
      ]
    },
