    "subTopics": [
      {
        "id": "sub-1",
        "title": "1. Mathematical Payoff Asymmetry: Why the Winner Outruns the Loser",
        "content": "\n          <p class=\"mb-3\">Options have asymmetric convexity. If you purchase CE at ₹45 and PE at ₹45 (Total Investment = ₹90 per share):</p>\n          <ul class=\"list-disc pl-5 mb-4 space-y-1.5 text-xs text-gray-300\">\n            <li><strong>Losing Leg (Worst Case):</strong> Cannot fall below ₹0. Maximum decay is capped at -₹45. In reality, you exit around ₹15 (loss capped at -₹30).</li>\n            <li><strong>Winning Leg (Best Case):</strong> Expands with delta and gamma, running to ₹140, ₹180, or ₹250 (+₹100 to +₹200 gain).</li>\n            <li><strong>Net Result:</strong> Winning Leg (+₹110) minus Losing Leg (-₹30) = <strong>+₹80 Net Profit per share (+88% overall portfolio return)</strong> with zero directional guesswork!</li>\n          </ul>\n        "
      },
      {
        "id": "sub-2",
        "title": "2. Spotting Pre-Breakout Range Contractions on Nifty & Sensex",
        "content": "\n          <p class=\"mb-3\">Do not deploy equal pairs randomly. The perfect condition is when Nifty has consolidated inside a narrow 40-point box for at least 75 minutes. The compression guarantees an explosive expansion release.</p>\n        "
      },
      {
        "id": "sub-3",
        "title": "3. Order Execution Protocol & Immediate Profit-Taking on 2x Blast",
        "content": "\n          <p class=\"mb-3\">Buy both CE and PE simultaneously using our Sniper Tool. As soon as the total combined basket profit hits +50%, book half. Trail the winning runner.</p>\n        "
      }
    ],
    "tradeDetails": {
      "setupType": "Delta-Neutral Volatility Expansion Strangle",
      "instrument": "Matched Equal CE & PE Strike Pair",
      "entryTrigger": "Simultaneous buy when CE and PE are balanced within ₹3 premium difference",
      "stopLoss": "Combined portfolio stop loss at -30% of total deployed basket capital",
      "target1": "Total combined investment reaches +50% net profit",
      "target2": "Total combined investment reaches +100% (2x) net profit",
      "riskReward": "1:2.8",
      "executionChecklist": [
        "Index is consolidating tightly near VWAP before an anticipated breakout",
        "Premiums of CE and PE are balanced within ₹3 of each other",
        "Both strikes have verified active open interest and tight bid-ask spreads",
        "Exit losing leg once it decays by 60% and ride winning leg runner"
      ],
      "pitfalls": [
        "Deploying equal pairs on dead holiday chop days where theta eats both legs",
        "Exiting the winning leg too early out of fear while holding the losing leg"
      ]
    },
